export function initializeLaunchHost(windowLike: unknown = getDefaultWindow()): LaunchHostContext {
  const context = detectLaunchHost(windowLike);

  if (context.platform === 'telegram') {
    const telegramWebApp = getTelegramWebApp(windowLike);
    try {
      telegramWebApp?.ready?.();
      telegramWebApp?.expand?.();
    } catch {
      void 0;
    }
  }

  return context;
}
```

