异常吞掉，避免宿主 API 不稳定时卡死启动。你拿到的仍是同一份 `LaunchHostContext`。

深链只解析 Telegram 房间码：

```ts
export function resolveHostStartPath(context: LaunchHostContext): string | null {
  if (context.platform !== 'telegram' || !context.startParam) return null;

  const directRoom = context.startParam.match(/^[a-z0-9]{6}$/i);
  const prefixedRoom = context.startParam.match(/^room[-_:]?([a-z0-9]{6})$/i);
  const roomCode = directRoom?.[0] ?? prefixedRoom?.[1] ?? null;

  return roomCode ? `/room/${roomCode.toUpperCase()}` : null;
}
```

